package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.*;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class AssetExportJobControllerTest {
    final String actor="7f000000-0000-4000-8000-000000000001",tenant="7f000000-0000-4000-8000-000000000002",id="7f000000-0000-4000-8000-000000000003";
    final Instant time=Instant.parse("2026-10-04T00:00:00Z");PlatformRepository platform;AssetExportJobRepository jobs;AssetExportJobController controller;ObjectMapper json=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);jobs=mock(AssetExportJobRepository.class);controller=new AssetExportJobController(platform,jobs);member("padmin",true);when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(jobs.accept(any(),any())).thenReturn(job(State.QUEUED,new Filters(null,null,null,null)));when(jobs.list(any(),anyInt(),any(),any())).thenReturn(List.of());}
    void member(String role,boolean active){when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,role,1,active)));}
    AssetExportJobRepository.Access access(){return new AssetExportJobRepository.Access(actor,tenant,1,"export-api-test");}
    Job job(State state,Filters f){return new Job(id,tenant,actor,1,"padmin","a".repeat(64),f,state,state==State.QUEUED?0:2,time,time);}
    ObjectNode input(){var n=json.createObjectNode().put("expected_version",0).put("mode",AssetExportJobController.MODE);n.putObject("filters").putNull("type").putNull("status").putNull("site_id").putNull("query");return n;}
    MockHttpServletRequest request(String method,String body){var r=new MockHttpServletRequest(method,"/api/v1/asset-export-jobs");r.setUserPrincipal(()->actor);r.getSession().setAttribute("mop.tenant_id",tenant);r.setAttribute("mop.trace_id","export-api-test");r.addHeader("Idempotency-Key","export-test-key");r.setContentType("application/json");r.setContent(body.getBytes(StandardCharsets.UTF_8));return r;}
    Map<?,?> data(Object result){return (Map<?,?>)((Map<?,?>)result).get("data");}
    Object accept(ObjectNode n){return controller.accept(request("POST",n.toString()));}
    @Test void acceptanceIsQueuedOnlyAndRechecksAuthorizationBeforeProtectedCallback(){var d=data(accept(input()));assertEquals(id,d.get("job_id"));assertEquals("QUEUED",d.get("status"));assertEquals(false,d.get("download_allowed"));assertEquals("NOT_IMPLEMENTED",d.get("publication_status"));verify(jobs).authorizeAcceptance(access());verify(jobs).accept(access(),new Filters(null,null,null,null));verify(jobs,never()).claimNext(any(),any());}
    @Test void modeAndZeroVersionMustBeExplicit(){for(ObjectNode n:List.of(input().put("mode","PUBLISH"),input().put("expected_version",1),input().put("expected_version",0.0),input().putNull("mode"))){assertEquals(400,assertThrows(DomainException.class,()->accept(n)).status);}var n=input();n.remove("mode");assertThrows(DomainException.class,()->accept(n));verifyNoInteractions(jobs);}
    @Test void allFilterFieldsRequiredAndCannotOverrideScope(){for(String key:List.of("type","status","site_id","query")){var n=input();((ObjectNode)n.get("filters")).remove(key);assertThrows(DomainException.class,()->accept(n));}for(String key:List.of("tenant_id","created_by","download_allowed","object_id")){var n=input().put(key,"injected");assertThrows(DomainException.class,()->accept(n));}verifyNoInteractions(jobs);}
    @Test void exactEmptyAndWhitespaceFiltersAreNotDefaulted(){var n=input();((ObjectNode)n.get("filters")).put("site_id","").put("query","  ");when(jobs.accept(any(),any())).thenReturn(job(State.QUEUED,new Filters(null,null,"","  ")));accept(n);verify(jobs).accept(access(),new Filters(null,null,"","  "));}
    @Test void filterTypeStatusAndLengthBoundsAreCheckedBeforeWrites(){for(String[] item:new String[][]{{"type","invalid"},{"status","healthy"},{"site_id","a".repeat(65)},{"query","a".repeat(101)}}){var n=input();((ObjectNode)n.get("filters")).put(item[0],item[1]);assertThrows(DomainException.class,()->accept(n));}var n=input();((ObjectNode)n.get("filters")).put("query",false);assertThrows(DomainException.class,()->accept(n));verifyNoInteractions(jobs);}
    @Test void duplicateTrailingDeepAndOversizedBodiesAreRejected(){for(String body:List.of(input()+" {}","{\"expected_version\":0,\"expected_version\":0}","{\"a\":{\"b\":{\"c\":{\"d\":1}}}}")){assertThrows(DomainException.class,()->controller.accept(request("POST",body)));}assertEquals(413,assertThrows(DomainException.class,()->controller.accept(request("POST"," ".repeat(8193)))).status);verifyNoInteractions(jobs);}
    @Test void missingOrInvalidIdempotencyKeyNeverDispatches(){var r=request("POST",input().toString());r.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.accept(r));r.addHeader("Idempotency-Key","bad key");assertThrows(DomainException.class,()->controller.accept(r));verifyNoInteractions(jobs);}
    @Test void canonicalRequestHashIgnoresObjectKeyOrder(){accept(input());controller.accept(request("POST","{\"filters\":{\"query\":null,\"site_id\":null,\"status\":null,\"type\":null},\"mode\":\"PREPARE_ONLY_NO_PUBLICATION\",\"expected_version\":0}"));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(2)).idempotentAuthorized(eq(actor),eq(tenant),eq("POST /api/v1/asset-export-jobs"),eq("export-test-key"),hashes.capture(),eq(1L),any(),any());assertEquals(hashes.getAllValues().get(0),hashes.getAllValues().get(1));}
    @Test void originalReceiptReplayStillInvokesCurrentAuthorization(){doAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("job_id",id,"status","QUEUED");}).when(platform).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());accept(input());verify(jobs).authorizeAcceptance(access());verify(jobs,never()).accept(any(),any());}
    @Test void customerRolesCannotReadOrAcceptAndInactiveIsUnauthorized(){for(String role:List.of("viewer","tadmin","unknown")){member(role,true);assertEquals(403,assertThrows(DomainException.class,()->accept(input())).status);assertEquals(403,assertThrows(DomainException.class,()->controller.list(request("GET",""))).status);}member("msp",false);assertEquals(401,assertThrows(DomainException.class,()->controller.list(request("GET",""))).status);assertEquals(401,assertThrows(DomainException.class,()->controller.list(new MockHttpServletRequest())).status);verifyNoInteractions(jobs);}
    @Test void mspCanReadOwnListWithNoDownloadOrWorkerAssumption(){member("msp",true);var d=data(controller.list(request("GET","")));assertEquals(actor,d.get("created_by"));assertNull(d.get("worker_liveness"));assertEquals(false,d.get("download_allowed"));verify(jobs).list(access(),16,null,null);}
    @Test void keysetLookaheadHasPairedTailAndExactLimit(){when(jobs.list(any(),anyInt(),any(),any())).thenReturn(Collections.nCopies(16,job(State.QUEUED,new Filters(null,null,null,null))));var d=data(controller.list(request("GET","")));assertEquals(15,((List<?>)d.get("items")).size());assertEquals(true,d.get("has_more"));assertEquals(id,d.get("next_before_id"));assertEquals(time,d.get("next_before_created_at"));}
    @Test void malformedDuplicateForeignAndOversizedQueryAreRejected(){for(String key:List.of("tenant_id","owner_id","download","before_id")){var r=request("GET","");r.addParameter(key,id);assertThrows(DomainException.class,()->controller.list(r));}var r=request("GET","");r.addParameter("page_size","15","20");assertThrows(DomainException.class,()->controller.list(r));var too=request("GET","");too.setQueryString("x="+"a".repeat(2048));assertThrows(DomainException.class,()->controller.list(too));verifyNoInteractions(jobs);}
    @Test void detailSeparatesNoFileFromExplicitEmptyPreparation(){var f=new Filters(null,null,null,null);when(jobs.progress(access(),id)).thenReturn(new Progress(job(State.RUNNING,f),1,null,null));var empty=data(controller.get(id,request("GET","")));assertNull(empty.get("prepared"));var e=new Encoding("a".repeat(64),"b".repeat(64),4,0,time);when(jobs.progress(access(),id)).thenReturn(new Progress(job(State.RUNNING,f),1,e,null));var d=data(controller.get(id,request("GET","")));assertEquals(0,((Map<?,?>)d.get("prepared")).get("row_count"));assertEquals(false,d.get("download_allowed"));for(String field:List.of("file_bytes","object_id","lease_owner","command_bytes","download_url"))assertFalse(d.containsKey(field));}
    @Test void detailPropagates404AndRejectsWrongProjectedScope(){when(jobs.progress(access(),id)).thenThrow(new DomainException(404,"OBJECT_NOT_FOUND","missing"));assertEquals(404,assertThrows(DomainException.class,()->controller.get(id,request("GET",""))).status);when(jobs.list(any(),anyInt(),any(),any())).thenReturn(List.of(new Job(id,tenant,id,1,"padmin","a".repeat(64),new Filters(null,null,null,null),State.QUEUED,0,time,time)));assertEquals(503,assertThrows(DomainException.class,()->controller.list(request("GET",""))).status);}
    @Test void returnedAcceptanceCannotMisstateFiltersOrState(){when(jobs.accept(any(),any())).thenReturn(job(State.RUNNING,new Filters(null,null,null,null)));assertEquals(503,assertThrows(DomainException.class,()->accept(input())).status);when(jobs.accept(any(),any())).thenReturn(job(State.QUEUED,new Filters(null,null,null,"changed")));assertEquals(503,assertThrows(DomainException.class,()->accept(input())).status);}
}
